import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for x in me if x == 'D')
    last_me, last_opp = history[-1]

    # Opening: signal willingness to cooperate.
    if n < 6:
        if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
            return 'D'
        return 'C'

    recent = opp[-8:]
    r_c = sum(1 for x in recent if x == 'C')
    r_d = len(recent) - r_c

    # Endgame: punish defectors, exploit persistent cooperators.
    if n >= 96:
        if opp_d == 0:
            return 'D'
        if opp_c == 0:
            return 'D'
        rate = opp_c / n
        if rate > 0.6:
            return 'D'
        if rate < 0.3:
            return 'D'
        return 'D' if last_opp == 'C' else 'C'

    # Hard-coded always-defect detection.
    if opp_c == 0:
        return 'D'

    # Persistent near-pure defector: stop rewarding.
    if n >= 15 and opp_c <= 1:
        return 'D'

    # Very cooperative opponent: exploit cautiously, but not so much as to
    # trigger retaliation. Keep occasional defection only late enough.
    if n >= 12 and opp_d == 0:
        if n >= 30 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # Long defection streak from opponent: retaliate hard.
    if r_d >= 4:
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Opponent just defected.
    if last_opp == 'D':
        # If we just defected too, and they've been mostly cooperative,
        # extend an olive branch to break mutual defection.
        if last_me == 'D' and r_c >= 5:
            return 'C'
        # If opponent's overall rate is high but they just defected,
        # treat as a probe; retaliate once then forgive.
        coop_rate = opp_c / n
        if coop_rate > 0.7 and r_d <= 1:
            return 'D'
        if r_d >= 3:
            return 'D'
        # Single defection: retaliate.
        return 'D'

    # Opponent just cooperated: reciprocate, but punish if we've been
    # exploited (they defect much more than us).
    if opp_d > my_d + 3 and n >= 20:
        # They've taken advantage; defect more.
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    # Slight probing against very cooperative opponents.
    if n > 40 and opp_d <= 2:
        if rng.random() < 0.08:
            return 'D'
        return 'C'

    # Punish long defection-heavy window from a mixed opponent.
    if r_d >= 3 and last_opp == 'C':
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    return 'C'
